/**
 * Hallucination Log — tool-local actions.
 *
 * Category: AI Quality / Eval Tools (squad S12a)
 * Tool:     Track LLM hallucinations across features, with severity,
 *           root cause, fix, and resolution timeline.
 *
 * Agent surface: tool.hallucination_log.*
 * Backing CRUD : workspace.hallucination.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (see daci.ts for the canonical reference) ──
 * Hallucinations are a record-keeping entity — generic create / list /
 * update / delete already exist via the auto-generated
 * workspace.hallucination.* surface. This file only adds VERBS THE AGENT
 * WANTS TO SPEAK in the hallucination-log's domain vocabulary, plus one
 * pure compute the agent can call during planning:
 *
 *   1. list_state              — snapshot + summary stats (bySeverity,
 *                                byRootCause, byFeature, open vs resolved).
 *                                Single round-trip "what's the state?".
 *   2. compute_severity_burden — pure: items in → numeric burden score
 *                                out. Open items weigh by severity; resolved
 *                                items contribute 0. Lets the agent reason
 *                                about "is this getting worse?" without
 *                                a workspace mutation.
 *   3. set_root_cause          — convenience over a workspace.hallucination
 *                                .update patch. After diagnosis the agent
 *                                tags the rootCause without marshalling a
 *                                full {patch: {rootCause: ...}} payload.
 *   4. mark_resolved           — close out a hallucination: stamp
 *                                resolvedAt AND record what fixApplied.
 *                                Both fields required — closing without
 *                                saying what fixed it loses the learning.
 *
 * ─── ID NAMING ───────────────────────────────────────────────────────
 * Namespace is `tool.hallucination_log` (snake_case — the route is
 * /hallucination-log, but registry ids use underscores so the
 * Anthropic dot→underscore munging stays unambiguous). The
 * auto-generated CRUD surface uses `workspace.hallucination` (the
 * entity type's single-word name); kindFromToolId maps that to
 * `workspace:hallucination` for server-store keys.
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { Hallucination } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.hallucination")
 *  used by the auto-generated CRUD in src/lib/actions/workspace/index.ts,
 *  so reads/writes here line up byte-for-byte with the generic surface. */
const KIND_HALLUCINATION = "workspace:hallucination";

/** Closed enum of valid severities. Matches the literal union in
 *  workspace-types.ts:Hallucination.severity verbatim. */
const SEVERITIES = ["low", "medium", "high", "critical"] as const;
const SeveritySchema = z.enum(SEVERITIES);

/** Closed enum of root-cause buckets. Matches the literal union in
 *  workspace-types.ts:Hallucination.rootCause verbatim. */
const ROOT_CAUSES = ["rag-miss", "prompt", "model", "context-window", "other"] as const;
const RootCauseSchema = z.enum(ROOT_CAUSES);

/** Severity weights for burden calculation. Reflects the rough operational
 *  cost of an unresolved hallucination in each tier: a critical one is ~15x
 *  the noise of a low one. The hallucination-log client uses these tiers
 *  for KPIs ("Critical open" gets its own counter), and the burden formula
 *  mirrors that emphasis — surfacing critical-heavy backlogs even when the
 *  total count is small. Resolved items contribute 0. */
const SEVERITY_WEIGHT: Record<Hallucination["severity"], number> = {
  low: 1,
  medium: 3,
  high: 7,
  critical: 15,
};

const ws = () => useWorkspaceStore.getState();

// ──────── tool.hallucination_log.list_state ────────
// Snapshot + summary stats. The agent's most common opening question
// for the hallucination log is "what's the state of AI quality?" —
// returning items[], breakdowns by severity / root cause / feature, AND
// open vs resolved counts in one round-trip avoids a follow-up reduce
// on the agent's end.
registry.register({
  id: "tool.hallucination_log.list_state",
  toolId: "tool.hallucination_log",
  name: "list_state",
  category: "read",
  description:
    "List all logged hallucinations with summary breakdowns. Returns {bySeverity: {low, medium, high, critical}, byRootCause: {rag-miss, prompt, model, context-window, other}, byFeature: Record<string, number>, openCount, resolvedCount, items}.",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = ws().hallucinations ?? [];
    return summarize(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<Hallucination>(ctx.userId, KIND_HALLUCINATION);
    return summarize(items);
  },
});

/** Build the {bySeverity, byRootCause, byFeature, openCount, resolvedCount,
 *  items} response shape. Kept as a single helper so the browser-path and
 *  MCP-path responses are guaranteed identical — drift here would mean an
 *  agent gets different shapes depending on whether it's invoked from chat
 *  or over MCP. */
function summarize(items: Hallucination[]) {
  // Initialise every severity key so the agent can index bySeverity.high
  // without an existence check, even when the workspace is empty.
  const bySeverity: Record<Hallucination["severity"], number> = {
    low: 0,
    medium: 0,
    high: 0,
    critical: 0,
  };
  // Initialise every root-cause key (using the enum, NOT the optional
  // undefined). Items with no rootCause set are excluded from this
  // breakdown — they show up in `items` so the agent can still see them.
  const byRootCause: Record<NonNullable<Hallucination["rootCause"]>, number> = {
    "rag-miss": 0,
    prompt: 0,
    model: 0,
    "context-window": 0,
    other: 0,
  };
  const byFeature: Record<string, number> = {};
  let openCount = 0;
  let resolvedCount = 0;

  for (const h of items) {
    // Defensive: a hand-crafted entity with an out-of-enum severity would
    // otherwise NaN the bucket. Skip silently for severity/rootCause
    // tallies — the items array still carries the row so the agent can
    // spot it if needed.
    if (h.severity in bySeverity) bySeverity[h.severity] += 1;
    if (h.rootCause && h.rootCause in byRootCause) byRootCause[h.rootCause] += 1;
    if (h.feature) byFeature[h.feature] = (byFeature[h.feature] ?? 0) + 1;
    if (h.resolvedAt) resolvedCount += 1;
    else openCount += 1;
  }

  return { bySeverity, byRootCause, byFeature, openCount, resolvedCount, items };
}

// ──────── tool.hallucination_log.compute_severity_burden ────────
// Pure: given a list of {severity, resolvedAt?}, compute a numeric
// "burden score" so the agent can decide what to prioritise. Open items
// contribute their severity weight (low=1, medium=3, high=7,
// critical=15); resolved items contribute 0.
//
// Why "read" not "write": this is referentially transparent — same
// inputs, same output, no side effects. The agent can call it with
// trial data ("what if we resolved the 3 highest?") without mutating
// anything. No mcpHandler — pure compute runs identically server/client.
registry.register({
  id: "tool.hallucination_log.compute_severity_burden",
  toolId: "tool.hallucination_log",
  name: "compute_severity_burden",
  category: "read",
  description:
    "Compute a numeric burden score for a batch of hallucinations. Open items contribute their severity weight (low=1, medium=3, high=7, critical=15); resolved items contribute 0. Optionally returns a per-feature breakdown when items carry a `feature`. Pure — no persistence.",
  paramsSchema: z.object({
    items: z
      .array(
        z.object({
          severity: SeveritySchema,
          resolvedAt: z.string().optional(),
          feature: z.string().optional(),
        })
      )
      .min(0)
      .max(2000),
  }),
  handler: async (params) => {
    let burdenScore = 0;
    const byFeature: Record<string, number> = {};
    let sawFeature = false;
    for (const it of params.items) {
      // Resolved items contribute 0 — they're learnings, not active load.
      if (it.resolvedAt) continue;
      const w = SEVERITY_WEIGHT[it.severity];
      burdenScore += w;
      if (it.feature) {
        sawFeature = true;
        byFeature[it.feature] = (byFeature[it.feature] ?? 0) + w;
      }
    }
    // Only include byFeature when at least one item carried a feature
    // tag — otherwise the {byFeature: {}} would be misleading noise.
    return sawFeature ? { burdenScore, byFeature } : { burdenScore };
  },
  // No mcpHandler — pure compute runs identically on server and client.
});

// ──────── tool.hallucination_log.set_root_cause ────────
// Convenience over workspace.hallucination.update. After diagnosis the
// agent tags the rootCause, and the generic update surface requires
// marshalling a full {patch: {rootCause: ...}} payload. Returns
// {updated: boolean} so the agent can detect missing-id without throwing.
registry.register({
  id: "tool.hallucination_log.set_root_cause",
  toolId: "tool.hallucination_log",
  name: "set_root_cause",
  category: "write",
  requiresConfirmation: false,
  description:
    "Tag the root cause on an existing hallucination after diagnosis (rag-miss | prompt | model | context-window | other). Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    rootCause: RootCauseSchema,
  }),
  handler: async (params) => {
    const items = ws().hallucinations ?? [];
    const current = items.find((h) => h.id === params.id);
    if (!current) return { updated: false };
    ws().upsertHallucination({ ...current, rootCause: params.rootCause });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<Hallucination>(ctx.userId, KIND_HALLUCINATION, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<Hallucination>(ctx.userId, KIND_HALLUCINATION, {
      ...current,
      rootCause: params.rootCause,
    });
    return { updated: true };
  },
});

// ──────── tool.hallucination_log.mark_resolved ────────
// Close out a hallucination: stamp resolvedAt + record what fixApplied.
// Both fields required — closing one without saying what fixed it is an
// anti-pattern (the next agent reading the log can't learn from it).
// resolvedAt defaults to "now" because the most common shape is "I just
// shipped the fix, mark this resolved". requiresConfirmation:false
// because it's additive — the existing data isn't overwritten, only
// augmented with resolution metadata.
registry.register({
  id: "tool.hallucination_log.mark_resolved",
  toolId: "tool.hallucination_log",
  name: "mark_resolved",
  category: "write",
  requiresConfirmation: false,
  description:
    "Mark a hallucination as resolved. Stamps resolvedAt (defaults to now) and records what fixApplied — fixApplied is required because closing a hallucination without saying what fixed it is an anti-pattern. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    fixApplied: z
      .string()
      .min(1)
      .max(2000)
      .describe("Short description of what was changed to fix the hallucination."),
    resolvedAt: z
      .string()
      .optional()
      .describe("ISO timestamp; defaults to the current time when omitted."),
  }),
  handler: async (params) => {
    const items = ws().hallucinations ?? [];
    const current = items.find((h) => h.id === params.id);
    if (!current) return { updated: false };
    ws().upsertHallucination({
      ...current,
      fixApplied: params.fixApplied,
      resolvedAt: params.resolvedAt ?? new Date().toISOString(),
    });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<Hallucination>(ctx.userId, KIND_HALLUCINATION, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<Hallucination>(ctx.userId, KIND_HALLUCINATION, {
      ...current,
      fixApplied: params.fixApplied,
      resolvedAt: params.resolvedAt ?? new Date().toISOString(),
    });
    return { updated: true };
  },
});
